    "sql": [
      "CREATE TABLE \"notes\" (\n\t\"id\" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,\n\t\"org_id\" uuid NOT NULL,\n\t\"title\" text DEFAULT '' NOT NULL,\n\t\"body\" text DEFAULT '' NOT NULL,\n\t\"pinned\" boolean DEFAULT false NOT NULL,\n\t\"idempotency_key\" text,\n\t\"created_by\" text,\n\t\"updated_by\" text,\n\t\"version\" integer DEFAULT 1 NOT NULL,\n\t\"created_at\" timestamp with time zone DEFAULT now() NOT NULL,\n\t\"updated_at\" timestamp with time zone DEFAULT now() NOT NULL,\n\tCONSTRAINT \"note_title_chk\" CHECK (char_length(\"notes\".\"title\") <= 200),\n\tCONSTRAINT \"note_body_chk\" CHECK (char_length(\"notes\".\"body\") <= 20000),\n\tCONSTRAINT \"note_not_empty_chk\" CHECK (char_length(\"notes\".\"title\") + char_length(\"notes\".\"body\") > 0)\n);\n",
      "\nALTER TABLE \"notes\" ADD CONSTRAINT \"notes_org_id_organizations_id_fk\" FOREIGN KEY (\"org_id\") REFERENCES \"public\".\"organizations\"(\"id\") ON DELETE cascade ON UPDATE no action;",
      "\nALTER TABLE \"notes\" ADD CONSTRAINT \"notes_created_by_user_id_fk\" FOREIGN KEY (\"created_by\") REFERENCES \"public\".\"user\"(\"id\") ON DELETE set null ON UPDATE no action;",
      "\nALTER TABLE \"notes\" ADD CONSTRAINT \"notes_updated_by_user_id_fk\" FOREIGN KEY (\"updated_by\") REFERENCES \"public\".\"user\"(\"id\") ON DELETE set null ON UPDATE no action;",
      "\nCREATE UNIQUE INDEX \"note_idempotency_uq\" ON \"notes\" USING btree (\"org_id\",\"idempotency_key\");",
      "\nCREATE INDEX \"note_org_idx\" ON \"notes\" USING btree (\"org_id\",\"pinned\",\"updated_at\");"
    ],
